// OpenControlWithResponse The node's control WebSocket
//
// Upgraded to a WebSocket of JSON text messages, each an object with a
// type: the node sends ControlHello first, and the hub answers
// ControlWelcome, or closes with status 4001 when the node's API
// version is older than the oldest the hub serves, its reason node,
// the side behind (hub_version_unsupported); a node newer than the
// hub is welcomed, and decides from the welcome's api_version what it
// can use. An older hub may close with the reason hub for a node newer
// than itself. The hub then sends
// ControlCertificate when two thirds of the node's certificate's life
// have passed, at the welcome and daily, which the node answers with
// ControlCertificateSaved once it wrote it, ControlStreamWaiting when
// another node asks for a stream to it, ControlNodeRemoved when
// another node of the account is removed from it, and ControlBye
// before it closes the connection. The node sends ControlState at each connect
// and whenever it changes. WebSocket pings keep it alive.
//
// Errors: node_revoked, account_disabled, as on every request of this
// endpoint.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /v1/control (the `OpenControl` operationId).
func (c *ClientWithResponses) OpenControlWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*OpenControlResponse, error) {
	rsp, err := c.OpenControl(ctx, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseOpenControlResponse(rsp)
}

// PushDocChangesWithBodyWithResponse Apply changes of the calling node's docs, in order
//
// Each change is applied once, in a transaction of its own, by the
// doc's id and revision: a change already applied is acknowledged
// again and nothing is written, so a batch sent again after a lost
// answer does nothing twice. A doc's revisions are sealed at rest
// under a data key of its own, which master_key seals. A body over
// 8 MiB is refused whole with usage.
//
// Each change is answered applied or refused with its code:
// revision_gap, a revision that is not the doc's next;
// revision_conflict, a revision the hub has with another text;
// doc_too_large, content that unpacks to more than 2 MiB;
// doc_name_taken, a name another of the user's docs of its kind in
// that repository has; not_found, a doc the hub does not have, or
// another user's; invalid_argument, a change that lacks what its kind
// needs.
//
// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /v1/docs/changes (the `PushDocChanges` operationId).
func (c *ClientWithResponses) PushDocChangesWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*PushDocChangesResponse, error) {
	rsp, err := c.PushDocChangesWithBody(ctx, contentType, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParsePushDocChangesResponse(rsp)
}

