// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAdminVersion Version of the hub, to its commands
	// (GET /v1/admin/version)
	GetAdminVersion(w http.ResponseWriter, r *http.Request)
	// VerifyAudit Walk the audit chain, checking every row's hash
	// (GET /v1/audit/verification)
	VerifyAudit(w http.ResponseWriter, r *http.Request)
	// Backup Copy the database, consistent, while the hub runs
	// (POST /v1/backup)
	Backup(w http.ResponseWriter, r *http.Request)
	// OpenControl The node's control WebSocket
	// (GET /v1/control)
	OpenControl(w http.ResponseWriter, r *http.Request)
	// PushDocChanges Apply changes of the calling node's docs, in order
	// (POST /v1/docs/changes)
	PushDocChanges(w http.ResponseWriter, r *http.Request)
	// CreateInvite Make an invite, a link that lets one person sign up
	// (POST /v1/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request)
	// StartNodeLogin Start making a machine one of an account's nodes
	// (POST /v1/node-logins)
	StartNodeLogin(w http.ResponseWriter, r *http.Request)
	// ExchangeNodeLogin Exchange a browser login's authorization code for the node's credentials
	// (POST /v1/node-logins/exchange)
	ExchangeNodeLogin(w http.ResponseWriter, r *http.Request)
	// PollNodeLogin Ask whether a device login was approved, as RFC 8628 has it
	// (POST /v1/node-logins/token)
	PollNodeLogin(w http.ResponseWriter, r *http.Request)
	// GetNodeVersion Version of the hub, to a node
	// (GET /v1/node/version)
	GetNodeVersion(w http.ResponseWriter, r *http.Request)
	// ListNodes The nodes of the calling node's account, by name
	// (GET /v1/nodes)
	ListNodes(w http.ResponseWriter, r *http.Request)
	// RemoveNode Revoke a node of the calling node's account, the caller among them
	// (DELETE /v1/nodes/{node})
	RemoveNode(w http.ResponseWriter, r *http.Request, node string)
	// GetNode One node of the calling node's account
	// (GET /v1/nodes/{node})
	GetNode(w http.ResponseWriter, r *http.Request, node string)
	// Reload Read the settings again and apply them
	// (POST /v1/reload)
	Reload(w http.ResponseWriter, r *http.Request)
	// ListSettings Every setting, with its value in the config file now
	// (GET /v1/settings)
	ListSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSetting Change a setting and apply it at once
	// (PATCH /v1/settings/{setting})
	UpdateSetting(w http.ResponseWriter, r *http.Request, setting string)
	// OpenStream Ask for a stream to another node of the calling node's account
	// (POST /v1/streams)
	OpenStream(w http.ResponseWriter, r *http.Request)
	// JoinStream Join a stream, as a WebSocket of binary messages
	// (GET /v1/streams/{id})
	JoinStream(w http.ResponseWriter, r *http.Request, id string)
	// ListUsers Every user not removed, by username
	// (GET /v1/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// RemoveUser Remove a user, keeping their username taken
	// (DELETE /v1/users/{user})
	RemoveUser(w http.ResponseWriter, r *http.Request, user UserRef)
	// GetUser One user, with their browser sessions counted and their nodes
	// (GET /v1/users/{user})
	GetUser(w http.ResponseWriter, r *http.Request, user UserRef)
	// UpdateUser Disable a user, or enable them again
	// (PATCH /v1/users/{user})
	UpdateUser(w http.ResponseWriter, r *http.Request, user UserRef)
	// CreateUserReset Make a password reset, a link that sets a user's password
	// (POST /v1/users/{user}/resets)
	CreateUserReset(w http.ResponseWriter, r *http.Request, user UserRef)
	// GetVersion Version of the hub
	// (GET /v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

