// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/version", wrapper.GetVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/node/version", wrapper.GetNodeVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/admin/version", wrapper.GetAdminVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/settings", wrapper.ListSettings)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/settings/{setting}", wrapper.UpdateSetting)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/reload", wrapper.Reload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/backup", wrapper.Backup)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/invites", wrapper.CreateInvite)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/users/{user}", wrapper.RemoveUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/users/{user}", wrapper.GetUser)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/users/{user}", wrapper.UpdateUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/users/{user}/resets", wrapper.CreateUserReset)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/audit/verification", wrapper.VerifyAudit)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/node-logins", wrapper.StartNodeLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/node-logins/exchange", wrapper.ExchangeNodeLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/node-logins/token", wrapper.PollNodeLogin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/control", wrapper.OpenControl)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/streams", wrapper.OpenStream)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams/{id}", wrapper.JoinStream)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/nodes", wrapper.ListNodes)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/nodes/{node}", wrapper.RemoveNode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/nodes/{node}", wrapper.GetNode)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/docs/changes", wrapper.PushDocChanges)

	return m
}

